void svr_format_job( /* <=== svr_format_job */ 

  FILE *fh,         /* output file handle */
  job  *pjob,       /* I */
  char *fmt,        /* printf-like format description */
  int   mailpoint,  /* note, single character  */
  char *text)       /* (optional) additional message text */

  {
    char *p, *stdmessage = NULL, *reason = NULL;

    /* First get the "standard" message */

    switch (mailpoint)
      {

      case MAIL_ABORT:

        stdmessage = msg_job_abort;
        reason = msg_job_abort;

        break;

      case MAIL_BEGIN:

        stdmessage = msg_job_start;
        reason = msg_job_start;

        break;

      case MAIL_END:

        stdmessage = msg_job_end;
        reason = msg_job_end;

        break;

      case MAIL_DEL:

        stdmessage = msg_job_del;
        reason = msg_job_del;

        break;

      case MAIL_STAGEIN:

        stdmessage = msg_job_stageinfail;
        reason = pbse_to_txt(PBSE_STAGEIN); /* NB: short version used */

        break;

      case MAIL_CHKPTCOPY:

        stdmessage = msg_job_copychkptfail;
	reason = msg_job_copychkptfail;

        break;

      case MAIL_OTHER:

      default:

        stdmessage = msg_job_otherfail;
        reason = msg_job_otherfail;

        break;
      }  /* END switch (mailpoint) */


    p = fmt;
    while (*p)
      {
      if (*p == '\\')      /* escape sequences */
        {
        switch(p[1])
          {
          case 'n':  /* newline */
            fputc('\n', fh);
            p += 2;
            break;
          case 't':  /* tab */
            fputc('\t', fh);
            p += 2;
            break;
          case '\\': /* backslash */
          case '\'': /* quote */
          case '\"': /* double-quote */
            fputc(p[1], fh);
            p += 2;
            break;
          default:  /* we don't recognise this escape, ignore it (catches p[1]==0) */
            fputc(*p++, fh);
            break;
          } /* END switch(p[1]) */
        }
        else if(*p == '%') /* format statement */
          {
          switch(p[1])
            {
            case 'd':  /* details */
              if (text != NULL)
                {
                fprintf(fh, "%s", text);
                }
              p += 2;
              break;
            case 'h':  /* host */
              if (pjob->ji_wattr[(int)JOB_ATR_exec_host].at_val.at_str != NULL)
                {
                fprintf(fh, "%s", pjob->ji_wattr[(int)JOB_ATR_exec_host].at_val.at_str);
                }
              p += 2;
              break;
            case 'i':  /* jobId */
              fprintf(fh, "%s", pjob->ji_qs.ji_jobid);
              p += 2;
              break;
            case 'j':  /* jobname */
              fprintf(fh, "%s", pjob->ji_wattr[(int)JOB_ATR_jobname].at_val.at_str);
              p += 2;
              break;
            case 'm':  /* stdmessage */
              if (stdmessage != NULL)
                {
                fprintf(fh, "%s", stdmessage);
                }
              p += 2;
              break;
            case 'r':  /* reason */
              if (reason != NULL)
                {
                fprintf(fh, "%s", reason);
                }
              p += 2;
              break;
            default:  /* we don't recognise this format, ignore it (catches p[1]==0) */
              fputc(*p++, fh);
              break;
            } /* END switch(p[1]) */
          }
        else               /* ordinary character */
          {
          fputc(*p++, fh);
          }
      } /* END while (*p) */
  } /* END format_job() */

void log_event( /* <=== log_event */ 

  int   eventtype,
  int   objclass,
  char *objname,
  char *text)

  {
  if (((eventtype & PBSEVENT_FORCE) == 0) &&
      ((*log_event_mask & eventtype) == 0))
    {
    return;  /* not logging this type of event */
    }

  log_record(eventtype, objclass, objname, text);

  return;
  }  /* END log_event() */

void net_close( /* <=== net_close */ 

  int but)  /* I */

  {
  int i;

  for (i = 0;i < max_connection;i++)
    {
    if (i != but)
      {
      svr_conn[i].cn_oncl = 0;

      close_conn(i);
      }
    }    /* END for (i) */

  return;
  }  /* END net_close() */

void write_email( /* <=== write_email */ 

  FILE      *outmail_input,
  job       *pjob,
  char      *mailto,
  int        mailpoint,
  char      *text)

  {
  char *bodyfmt = NULL;
  char  bodyfmtbuf[MAXLINE];
  char *subjectfmt = NULL;

  /* Pipe in mail headers: To: and Subject: */
  fprintf(outmail_input, "To: %s\n", mailto);

  /* mail subject line formating statement */
  if ((server.sv_attr[SRV_ATR_MailSubjectFmt].at_flags & ATR_VFLAG_SET) &&
      (server.sv_attr[SRV_ATR_MailSubjectFmt].at_val.at_str != NULL))
    {
    subjectfmt = server.sv_attr[SRV_ATR_MailSubjectFmt].at_val.at_str;
    }
  else
    {
    subjectfmt = "PBS JOB %i";
    }

  fprintf(outmail_input, "Subject: ");
  svr_format_job(outmail_input, pjob, subjectfmt, mailpoint, text);
  fprintf(outmail_input, "\n");

  /* Set "Precedence: bulk" to avoid vacation messages, etc */
  fprintf(outmail_input, "Precedence: bulk\n\n");

  /* mail body formating statement */
  if ((server.sv_attr[SRV_ATR_MailBodyFmt].at_flags & ATR_VFLAG_SET) &&
      (server.sv_attr[SRV_ATR_MailBodyFmt].at_val.at_str != NULL))
    {
    bodyfmt = server.sv_attr[SRV_ATR_MailBodyFmt].at_val.at_str;
    }
  else
    {
    bodyfmt =  strcpy(bodyfmtbuf, "PBS Job Id: %i\n"
                                  "Job Name:   %j\n");
    if (pjob->ji_wattr[JOB_ATR_exec_host].at_flags & ATR_VFLAG_SET)
      {
      strcat(bodyfmt, "Exec host:  %h\n");
      }

    strcat(bodyfmt, "%m\n");

    if (text != NULL)
      {
      strcat(bodyfmt, "%d\n");
      }
    }

  /* Now pipe in the email body */
  svr_format_job(outmail_input, pjob, bodyfmt, mailpoint, text);
  } /* write_email() */

void /* <=== rpp_terminate */ 
rpp_terminate(void)

  {

  struct stream  *sp;

  struct send_packet *spp;

  struct pending  *ppp;

  struct recv_packet *rpp;
  int   i;

  for (i = 0;i < rpp_fd_num;i++)
    close(rpp_fd_array[i]);

  if (rpp_fd_array)
    {
    free(rpp_fd_array);

    rpp_fd_array = NULL;
    rpp_fd_num = 0;
    }

  for (i = 0;i < stream_num;i++)
    {
    sp = &stream_array[i];

    if (sp->state == RPP_DEAD)
      continue;

    for (ppp = sp->pend_head;ppp != NULL;ppp = sp->pend_head)
      {
      free(ppp->data);

      sp->pend_head = ppp->next;

      free(ppp);
      }

    for (rpp = sp->recv_head;rpp != NULL;rpp = sp->recv_head)
      {
      if (rpp->data != NULL)
        free(rpp->data);

      sp->recv_head = rpp->next;

      free(rpp);
      }

    for (spp = sp->send_head;spp != NULL;spp = sp->send_head)
      {
      free(spp->data);

      sp->send_head = spp->next;

      free(spp);
      }
    }

  top = NULL;

  bottom = NULL;

  if (stream_array)
    free(stream_array);

  stream_num = 0;

  stream_array = NULL;

  rpp_fd = -1;

  return;
  }  /* END rpp_terminate() */

void close_conn( /* <=== close_conn */ 

  int sd) /* I */

  {

  if ((sd < 0) || (max_connection <= sd))
    {
    return;
    }

  if (svr_conn[sd].cn_active == Idle)
    {
    return;
    }

  close(sd);

  /* if there is a function to call on close, do it */

  if (svr_conn[sd].cn_oncl != 0)
    svr_conn[sd].cn_oncl(sd);

  /* 
   * In the case of a -t cold start, this will be called prior to
   * GlobalSocketReadSet being initialized
   */

  if (GlobalSocketReadSet != NULL)
  {
    FD_CLR(sd, GlobalSocketReadSet);
  }

  svr_conn[sd].cn_addr = 0;

  svr_conn[sd].cn_handle = -1;

  svr_conn[sd].cn_active = Idle;

  svr_conn[sd].cn_func = (void (*)())0;

  svr_conn[sd].cn_authen = 0;

  num_connections--;

  DIS_tcp_close(sd);


  return;
  }  /* END close_conn() */

